20	import ZRText from 'zrender/src/graphic/Text';
21	import { LabelExtendedTextStyle, LabelLayoutOption, LabelMarginType, NullUndefined } from '../util/types';
22	import {
23	    BoundingRect, OrientedBoundingRect, Polyline, expandOrShrinkRect,
24	    isBoundingRectAxisAligned
25	} from '../util/graphic';
26	import type Element from 'zrender/src/Element';
27	import { PointLike } from 'zrender/src/core/Point';
28	import { each, extend, retrieve2 } from 'zrender/src/core/util';
29	import { normalizeCssArray } from '../util/format';
30	import { BoundingRectIntersectOpt } from 'zrender/src/core/BoundingRect';
31	import { MatrixArray } from 'zrender/src/core/matrix';
