219	    adjustSingleSide(rightList, cx, cy, r, 1, viewWidth, viewHeight, viewLeft, viewTop, rightmostX);
220	    adjustSingleSide(leftList, cx, cy, r, -1, viewWidth, viewHeight, viewLeft, viewTop, leftmostX);
221	
222	    for (let i = 0; i < labelLayoutList.length; i++) {
223	        const layout = labelLayoutList[i];
224	        if (!isPositionCenter(layout) && layout.linePoints) {
225	            const label = layout.label;
226	            const linePoints = layout.linePoints;
227	            const isAlignToEdge = layout.labelAlignTo === 'edge';
228	            const padding = label.style.padding as number[];
229	            const paddingH = padding ? padding[1] + padding[3] : 0;
230	            // textRect.width already contains paddingH if bgColor is set
231	            const extraPaddingH = label.style.backgroundColor ? 0 : paddingH;
232	            const realTextWidth = layout.rect.width + extraPaddingH;
