464	        }
465	
466	        const PI = Math.PI;
467	        let labelRotate = 0;
468	        const rotate = labelModel.get('rotate');
469	        if (isNumber(rotate)) {
470	            labelRotate = rotate * (PI / 180);
471	        }
472	        else if (labelPosition === 'center') {
473	            labelRotate = 0;
474	        }
475	        else if (rotate === 'radial' || rotate === true) {
476	            const radialAngle = nx < 0 ? -midAngle + PI : -midAngle;
477	            labelRotate = radialAngle;
478	        }
479	        else if (rotate === 'tangential'
