513	    private _animateLabels(el: Element, seriesModel: SeriesModel) {
514	        const textEl = el.getTextContent();
515	        const guideLine = el.getTextGuideLine();
516	        // Animate
517	        if (textEl
518	            // `forceLabelAnimation` has the highest priority
519	            && ((el as ECElement).forceLabelAnimation
520	                || !textEl.ignore
521	                && !textEl.invisible
522	                && !(el as ECElement).disableLabelAnimation
523	                && !isElementRemoved(el)
524	            )
525	        ) {
526	            const layoutStore = labelLayoutInnerStore(textEl);
527	            const oldLayout = layoutStore.oldLayout;
528	            const ecData = getECData(el);
529	            const dataIndex = ecData.dataIndex;
530	            const newProps = {
531	                x: textEl.x,
532	                y: textEl.y,
533	                rotation: textEl.rotation
534	            };
535	            const data = seriesModel.getData(ecData.dataType);
536	
537	            if (!oldLayout) {
538	                textEl.attr(newProps);
539	                // Disable fade in animation if value animation is enabled.
540	                if (!labelInner(textEl).valueAnimation) {
541	                    const oldOpacity = retrieve2(textEl.style.opacity, 1);
542	                    // Fade in animation
543	                    textEl.style.opacity = 0;
544	                    initProps(textEl, {
545	                        style: { opacity: oldOpacity }
546	                    }, seriesModel, dataIndex);
547	                }
548	            }
549	            else {
550	                textEl.attr(oldLayout);
551	
552	                // Make sure the animation from is in the right status.
553	                const prevStates = el.prevStates;
554	                if (prevStates) {
555	                    if (indexOf(prevStates, 'select') >= 0) {
556	                        textEl.attr(layoutStore.oldLayoutSelect);
557	                    }
558	                    if (indexOf(prevStates, 'emphasis') >= 0) {
559	                        textEl.attr(layoutStore.oldLayoutEmphasis);
560	                    }
561	                }
562	                updateProps(textEl, newProps, seriesModel, dataIndex);
563	            }
564	            layoutStore.oldLayout = newProps;
565	
566	            if (textEl.states.select) {
567	                const layoutSelect = layoutStore.oldLayoutSelect = {};
568	                extendWithKeys(layoutSelect, newProps, LABEL_LAYOUT_PROPS);
569	                extendWithKeys(layoutSelect, textEl.states.select, LABEL_LAYOUT_PROPS);
570	            }
571	
572	            if (textEl.states.emphasis) {
573	                const layoutEmphasis = layoutStore.oldLayoutEmphasis = {};
574	                extendWithKeys(layoutEmphasis, newProps, LABEL_LAYOUT_PROPS);
575	                extendWithKeys(layoutEmphasis, textEl.states.emphasis, LABEL_LAYOUT_PROPS);
576	            }
577	
578	            animateLabelValue(textEl, dataIndex, data, seriesModel, seriesModel);
579	        }
580	
581	        if (guideLine && !guideLine.ignore && !guideLine.invisible) {
582	            const layoutStore = labelLineAnimationStore(guideLine);
583	            const oldLayout = layoutStore.oldLayout;
584	            const newLayout = { points: guideLine.shape.points };
585	            if (!oldLayout) {
586	                guideLine.setShape(newLayout);
587	                guideLine.style.strokePercent = 0;
588	                initProps(guideLine, {
589	                    style: { strokePercent: 1 }
590	                }, seriesModel);
591	            }
592	            else {
593	                guideLine.attr({ shape: oldLayout });
594	                updateProps(guideLine, {
595	                    shape: newLayout
596	                }, seriesModel);
597	            }
598	
599	            layoutStore.oldLayout = newLayout;
600	        }
601	    }
